insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('09d8545a-fe44-4389-9038-a491c40cecc6','zh','night-before-the-storm','暴风前夜','《突袭2》停运前，Nexon工作人员自信发言反成"回旋镖"的事件','2016年7月5日《突袭2》公测在即，Nexon相关人士在Facebook诉说开发过程的艰辛，并写下"结果会证明一切"之类的话。然而《突袭2》上线仅三周便宣布停止运营，结果与发言完全相反。此后，这句话被用作"信心满满地预告，最终却惨遭失败"情形的代称，沿用至今。','2016年7月《突袭2》上线前夕，Nexon相关人士的社交网络发言','信心满满地预告某事却惨遭失败时引用',NULL,array['폭풍전야']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('26511f54-a9aa-4de6-ab10-93bf8f669c48','zh','marine-corps-literature','海军陆战队文学','夸张讽刺海军陆战队体罚文化的网络创作小说类型','该类型起源于退伍海军陆战队员将过去被体罚的经历当作英雄事迹回忆讲述的帖子，后来发展成刻意夸张讽刺这种文化的创作文学类型。其完成度之高甚至形成了独立的世界观与人物设定，2022年仍在网络社区中被积极消费，已成为一种独立的meme类型。','对海军陆战队贴吧（해갤）中体罚回忆帖进行讽刺创作而产生的帖子','需理解这是熟悉军队文化的成年人社区中被当作讽刺作品消费的类型后再接触','内容以真实军队体罚为题材进行夸张讽刺，可能会让人感到不适',array['해병문학','海军陆战队贴吧文学']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('31053a14-7651-4c84-99cc-a2741e011ebc','zh','y2k-millennium-bug','Y2K千年虫（千禧年问题）','1999年末跨入新千年之际，围绕电脑故障蔓延的社会性恐慌','从1999年12月31日跨入2000年1月1日之际，社会上曾担忧电脑系统会因日期处理错误而瘫痪，甚至一度出现抢购防灾物资的骚动，但实际上并未造成重大损失，风波平稳过去。','Y2K（千年虫）问题源于计算机只识别年份末两位数字，会把2000年误判为1900年，从而可能引发系统全面瘫痪的担忧。1999年1月起，《京乡新闻》等韩国媒体接连报道"金融网络瘫痪、通讯中断可能使社会陷入恐慌"，令韩国社会整体高度紧张，政府与企业在下半年全力投入系统与网络排查。此间病毒与黑客攻击趁机猖獗，进一步加剧了不安情绪，但新年伊始并未发生重大事故，最终被评价为一场"茶杯里的风暴"。','可作为夸大的恐慌最终平安无事的案例引用',NULL,array['Y2K 밀레니엄버그','2000年问题','千年虫']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('42b5ffcf-5305-409d-9a8e-867e5c9cf03a','zh','pure-study-time','纯学习时间','去除休息时间后真正专注学习的时长','该词并非指坐在书桌前的全部时间，而是专指除去上厕所、吃饭等间隙后，真正专注学习的时间。考生们常用学习计时App测量并晒出"纯学习时间"，这一用法因此广泛流传。','确切起源时间不详，但自学习时间测量文化形成的2010年代后期起，该词已在考生社区中广泛使用。','用于描述实际专注学习的时间',NULL,array['순공시간','纯学习']::text[],'[]'::jsonb,'machine','2026-07-16T05:26:04.531944+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('484e0b56-97b1-4910-8fa6-2ea0348d28ca','zh','lim-yo-hwan-terran-emperor','林遥焕"人族皇帝"','星际争霸初期人气最高的职业选手林遥焕的绰号','在人族被视为劣势种族的年代，林遥焕凭借独特的生化步兵操作与新颖战术横扫各类赛事，获得"人族皇帝"绰号。此后他更被直接称为"皇帝"，不再区分种族限定，成为2000年代初电竞界最耀眼的明星。','"人族皇帝"是星际争霸1.07版本时期，人族普遍被认为处于劣势的年代，林遥焕凭借独特的生化步兵操作与新颖战术横扫各类赛事而获得的绰号。他在OnGameNet星际联赛实现两连冠，两大联赛累计三次夺冠，并且是唯一一位在WCG星际争霸项目连续两届夺得金牌的选手。凭借这些战绩，"皇帝"称号逐渐固定下来，此后即使不加任何修饰词，人们也直接称呼他为"皇帝"，成为电竞初期的标志性人物。','可作为韩国电竞初期代表明星的案例引用',NULL,array['임요환','테란의 황제','人族皇帝','皇帝']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5c1d93ba-de39-4993-9921-837a440ba0f1','zh','jjaljup-picture-collecting','捡图','把网络上流传的搞笑图片（짤방）收集起来的行为','该词由"짤（짤방，即防裁图）"与"줍다（捡）"组合而成，指把社区或社交网络上流传的有趣图片下载收集起来的行为。专门制作这类图片的人则被另称为"짤쟁이"。','指防止帖子被删除而附上的图片"짤방"一词，于2002年起源自DC Inside，随后指收集这类图片行为的"짤줍"一词也随之流行开来。','用于形容把喜欢的图片保存收藏起来的行为',NULL,array['짤줍']::text[],'[]'::jsonb,'machine','2026-07-16T05:26:04.531944+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6d0d7867-c77d-4a68-ad35-aa3ea7002aff','zh','tamagotchi-korea-1997','电子鸡（拓麻歌子）','1997年在韩国正式发售后，在小学生间掀起爆发式人气的掌上养成游戏机','1997年在韩国正式发售的电子鸡在小学生中掀起爆发式人气，因其频繁发出的提示音影响课堂秩序，甚至促使韩国教育部于1997年向全国教育厅下发禁止携带电子鸡入校的公文，一度成为社会问题。','电子鸡是日本万代公司于1996年推出的掌上虚拟宠物养成机，1997年经由大元动画在韩国正式发售。上市初期，报纸科学版面曾将其作为"日本的神奇游戏机"加以介绍，到4、5月已发展到经济版面报道其进口量与销售额的程度，成为社会话题，并在中小学女生中掀起爆发式人气。然而，由于上课期间频繁响起的提示音带来困扰，1997年5月30日韩国教育部向全国教育厅下发公文，禁止学生携带电子鸡入校，事件一度演变为社会争议。','可作为1990年代末小学生电子玩具热潮的代表案例引用',NULL,array['다마고치','电子鸡热潮']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7d2b68f7-6f4b-4ea6-adc2-63fbe4ad1813','zh','elastine-hair-is-skin-slogan','Elastine广告语：你的头发，对Elastine而言就是肌肤','全智贤代言11年，让Elastine洗发水这句广告语深入人心','2001年上市的LG生活健康Elastine洗发水，首位代言人全智贤，让"你的头发，对Elastine而言就是肌肤"这句广告语与"做了Elastine护理"这句台词广为流传。全智贤此后连续11年担任品牌代言人，助力该品牌稳居韩国洗发水市场头把交椅。这句广告语也被认为是最早将"头发也要像肌肤一样护理"这一理念普及给大众的经典文案。','2001年LG生活健康Elastine电视广告，全智贤出演','在强调头发护理时常被引用的经典长寿广告语',NULL,array['엘라스틴 당신의 머리 엘라스틴에겐 피부입니다','做了Elastine护理']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8894446b-fd8f-41b1-b870-5b3cc78615d7','zh','lck-four-mid-laners','四大中单','并称LCK四位巅峰中单选手的说法','2020年LCK夏季赛，Faker、ShowMaker、Chovy、BDD四人分别效力于T1、DWG、Gen.G、DRX，凭借远超其他选手的实力占据榜单前列，四人由此被合称为"四大中单"。最初曾按实力排序被称为"쇼쵸비페"（ShowMaker-Chovy-BDD-Faker首字组合），此后更具开放解读空间的"四大中单"说法逐渐流行开来。自四人于2019年悉数加入LCK之后，此后的LCK总决赛几乎从未缺席过其中之一，形成极具象征性的格局。','2020年LCK夏季赛，指代Faker、ShowMaker、Chovy、BDD四人','用于并称代表一个时代的四位最强者',NULL,array['4대 미드','쇼쵸비페']::text[],'[]'::jsonb,'machine','2026-07-16T07:53:05.760898+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8eeb7948-0920-4370-86e9-83ccc26f0c69','zh','love-house-renovation-show','爱心屋','2000年开播的房屋改造综艺鼻祖','2000年11月开播的MBC《星期日星期日晚上》"爱心屋"环节，通过创意改造恶劣居住环境而广受欢迎，助力申东烨成功回归荧屏，此后一直被视为房屋改造综艺类型的鼻祖。','爱心屋于2000年11月5日作为MBC《星期日星期日晚上》的一个环节开播，一直播出至2005年2月27日，是一档房屋改造类综艺。申东烨担任首任主持人，此后由朴洙弘、尹晶洙接棒，建筑师梁镇硕、南宫善、金元哲、李昌夏等出演，为居住环境恶劣的普通人彻底翻新住房，引发广泛话题。该节目以感动而非搞笑为主要基调，被评价为打破了综艺与纪录片的界限，也被视为韩国房屋改造综艺类型的鼻祖。','可作为房屋改造综艺鼻祖案例引用',NULL,array['러브하우스','申东烨的爱心屋']::text[],'[]'::jsonb,'machine','2026-07-16T07:53:05.760898+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('99e3b08f-53b7-4c6d-af0e-273349c7e0d9','zh','pre-peeled-egg-meme','预先剥壳的鸡蛋','讽刺塑料包装过度的美国搞笑图，在韩国也曾流行一时','这是运营美国讽刺网站Obvious Plant的杰夫·怀索斯基（Jeff Wysaski）于2018年11月2日制作的搞笑图，将生鸡蛋壳预先剥好后重新包装，制造出荒诞效果。该图传入韩国后，原图中的拼写错误"fimally"被直接照搬翻译使用，衍生出"마참내"（本应为"마침내"，即"终于"，此处为刻意模仿原图错拼而造的词）这一说法，成为韩国社区独有的流行语。','美国讽刺账号Obvious Plant的帖子（2018年11月）','用于调侃过度低效的产品或服务',NULL,array['껍질 미리 깐 달걀','마참내 달걀짤']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9b4799c1-3a32-4025-9559-1c94f9a89946','zh','infinite-challenge-buddy-special','《无限挑战》搭档特辑','借用SBS《配对》形式，寻找同性挚友的《无限挑战》恋爱模仿特辑','2011年10月22日、29日播出的《无限挑战》第272~273期特辑。借用了SBS恋爱真人秀《配对（짝）》的标题与概念，区别在于寻找的不是异性伴侣，而是同性挚友。从入住"友情村"开始展开的成员间化学反应与角色对决广受好评，在2025年《无限挑战》20周年TOP20问卷调查中位列第7名。','2011年10月22日MBC《无限挑战》第272期播出','常被无限挑战粉丝自评为传奇特辑而提及',NULL,array['무한도전 짝꿍','无限挑战搭档特辑']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('a158c5b1-fce3-4d7d-90d2-fda3f2f4459b','zh','king-muscle-goldmon','King肌肉黄金怪','宝可梦面包再版热潮中，DC Inside上诞生的宝可梦拼接恶搞角色','2022年3月宝可梦面包再版上市，相关的贴纸帖子层出不穷之际，DC Inside宝可梦吧一名用户把不受欢迎的宝可梦贴纸手脚剪下拼接而成的合成角色，取名"King肌肉黄金怪"并发布。该帖子随后传播至多个网络社区与推特，转发量超过一万次，获得了带有邪典色彩的人气。','DC Inside宝可梦吧发布的宝可梦贴纸合成帖（2022年3月）','用于形容虽然粗糙但很搞笑的拼接合成作品',NULL,array['킹근육골드몬']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('a9fd21c7-2bd4-4551-a530-cee10116a0b0','zh','todays-workout-hashtag','今日份运动打卡','"오늘 하루 운동"（今日份运动）的缩写，社交网络运动打卡话题标签','指每天记录并分享当日运动情况的文化，常以Instagram话题标签#오하운（#今日份运动）广泛使用。随着新冠疫情长期化，自我管理趋势扩散，这一用语随之流行开来。','首尔大学教授金兰都等人编著的《趋势韩国2021》一书将其收录为当年的年度流行新造词，2021年由此广为人知。','用作每日运动打卡帖的话题标签',NULL,array['오하운','今日份运动']::text[],'[]'::jsonb,'machine','2026-07-16T05:22:57.120679+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('ac093b70-85cf-4e1a-b2f6-bdc6093cabfc','zh','jang-seung-eop-necessary-element','张承业','朝鲜后期画家之名借DC Inside"啊嗨嗨"流行语被恶搞的必备素材','朝鲜后期真实存在的画家张承业之名，2002年在DC Inside随"啊嗨嗨（아햏햏）"流行语一同被恶搞，配上"世人怎么说都无所谓，我就是我！啊嗨嗨"之类的台词，成为当时的"必备素材（필수요소，指被广泛套用的梗）"。','2002年上映的林权泽导演电影《醉画仙》中，崔岷植饰演的朝鲜后期画家张承业，被塑造成一个超越世俗框架、充满自由不羁艺术魂的人物形象。同年，DC Inside"啊嗨嗨"流行语与"废人文化"正盛行，这一角色形象恰好与当时的氛围相契合，被配上"啊嗨嗨哟"之类的台词，作为恶搞性"必备素材"广泛传播。此后衍生出以他名字命名的"承业嗨字"说法，与딸녀、개벽이等一起，成为2002年DC Inside早期"必备素材"的代表性题材之一。','作为"啊嗨嗨"相关必备素材案例引用',NULL,array['장승업','承业嗨字']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('ae4ea7b7-8c35-4c01-8d2f-1e5c632b9a89','zh','pump-it-up-rhythm-game','Pump It Up','借DDR人气登场的韩国产音乐游戏机，2000年代初风靡游戏厅','受DDR人气刺激，Andamiro公司开发的"Pump It Up"在2000年代初的韩国游戏厅中，取代原版DDR成为最强者。虽然与科乐美之间曾发生外观设计权纠纷，但于2002年和解收场，成为韩国产音乐游戏的成功案例。','韩国企业Andamiro在日本DDR席卷游戏厅的1999年，首次推出了针对性的韩国产音乐游戏"Pump It Up"。该作将踏板布局与曲目构成调整得更符合韩国玩家口味，效果显著，到2000年前后已取代DDR，称霸游戏厅音乐游戏市场。当时在街头练习霹雳舞的青少年们纷纷聚集到亮着灯光的Pump机台前，使其超越单纯的游戏，发展成一种游戏文化。此后随着《暗黑破坏神2》的走红，游戏厅人群逐渐转移至网吧，这股热潮也随之逐渐降温。','可作为2000年代初游戏厅音乐游戏文化的代表案例引用',NULL,array['펌프 잇업','Pump']::text[],'[]'::jsonb,'machine','2026-07-16T07:53:05.760898+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b57eb7cb-6577-4543-9dbb-a397aa4e3e03','zh','fan-fiction-kpop','粉丝小说（Fan Fiction）','粉丝以偶像为主角创作的二次创作小说','始于1990年代后期H.O.T、god等第一代偶像粉丝圈的文化，粉丝们把偶像成员直接设定为小说角色，创作恋爱、日常向小说，并连载于网络社区或专门的粉丝小说网站。历经数代传承，如今在推特等平台上仍是粉丝圈代表性的二次创作活动之一。','第一代偶像粉丝圈（H.O.T、god时代，1990年代后期）','因涉及真实人物，提及本人或所属公司时需格外谨慎',NULL,array['팬픽','粉丝小说','팬픽션']::text[],'[]'::jsonb,'machine','2026-07-21T01:57:29.702804+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('b8ba9944-b9cb-4b72-82a8-8465089eda59','zh','gukmin-hakgyo-renamed','"国民学校"更名为"初等学校"','1996年3月为清除日据残余，将"国民学校"改称为"初等学校"的事件','日据时期1941年由总督府敕令赋予的"国民学校"名称，历经光复50周年的1995年韩国教育部发布及法律修订，于1996年3月1日起正式变更为"初等学校"。这是清除日据残余的象征性举措，在这一时期就读的一代人也常以"国民学校生（국딩）"自称加以区分。','1995年8月11日，韩国教育部长官正式宣布名称变更，其背景正值光复50周年，提出"清除日据残余、树立民族正气"的宗旨。"国民学校"这一名称源自1941年日本殖民当局敕令，是"皇国臣民学校"的简称，长期被指带有浓厚的军国主义色彩。经过一段准备期后，1996年3月1日起，全国小学统一开始使用新名称。这被视为光复50余年后才得以清理的殖民地残余的代表案例，这一时期就读的一代人也常自称"国民学校最后一代"。','可作为清除日据残余及世代划分的历史案例引用',NULL,array['국민학교→초등학교 개칭','国民学校名称变更']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('becc9e24-e54c-4a77-b749-d5044b327424','zh','marine-blues-webtoon','海洋布鲁斯','2001年开始连载，第一代网络漫画代表作之一','在"웹툰（网络漫画）"一词尚未普及的2001年11月开始连载，是郑哲演创作的漫画，被视为第一代网络漫画的代表作之一。','设计师郑哲演将自己与身边人物角色化后创作的生活向漫画，2001年11月首次在网络上连载。该作品诞生于"웹툰"一词尚未固定使用的时期，比姜草等其他第一代作者早了约两年，被视为开启网络漫画早期的作品。作品以"海胆君"等小人物角色，描绘青年世代的日常与孤独，引发共鸣，连载持续至2007年，被认为为此后出现的生活向漫画类型提供了原型。','在介绍第一代网络漫画文化时提及',NULL,array['마린블루스']::text[],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('bf40e19e-f3a6-456f-b513-dc9b2be21539','zh','pepe-the-frog','悲伤蛙佩佩（Pepe the Frog）','以漫画青蛙角色表达多种情绪的原版图片梗鼻祖','2005年Matt Furie漫画《Boy''s Club》中的角色佩佩，自2008年前后开始，作为表达悲伤、悠闲等多种情绪的图片梗广泛传播。国内社区也长期将其作为"悲伤反应图"使用，但在海外，曾有部分极端社区将其挪用为仇恨符号，因此是一个对语境较为敏感的meme。国内则大多作为单纯的反应图消费。','漫画《Boy''s Club》角色，Pepe the Frog（2005年原作，2008年成为meme）','由于在海外曾被极端主义挪用，在国际化语境场合需谨慎使用',NULL,array['페페 더 프로그','페페','佩佩','悲伤蛙']::text[],'[]'::jsonb,'machine','2026-07-21T01:57:30.257416+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
